// R_NamesSymbol — static SYMSXP sentinel for the "names" attribute key.
//
// Real declaration in Rinternals.h line 448:
//   LibExtern SEXP  R_NamesSymbol;    /* "names" */
//
// The complete definition is provided by SEXP.h under the guard
// FAKE_R_NAMESSYMBOL_DEFINED.  It reads:
//
