//       static SEXPREC names_sym = { SYMSXP, 0, 0, 0, NULL };
//       return &names_sym;
//   }
//   static SEXP R_NamesSymbol = make_names_symbol();
//
// Fields of the sentinel SEXPREC:
//   type   = SYMSXP (1) — consistent with a symbol node.
//   length = 0          — symbols are not vectors; length is irrelevant.
//   nrow   = 0          — not a matrix.
//   ncol   = 0          — not a matrix.
//   data   = NULL       — the symbol name string is not accessed anywhere
//                         in the rpart source; nullptr is safe.
//
// The function-static inside make_names_symbol() guarantees that a single
// SEXPREC object is allocated process-wide (first-call-wins).  The
// module-level `static SEXP R_NamesSymbol` in each translation unit stores
// the same address, so pointer equality holds across all .cpp files that
// include this header.
//
// No pointer dereference of R_NamesSymbol occurs at rpart.c:329 because
// setAttrib is defined as:
//   inline void Rf_setAttrib(SEXP /*x*/, SEXP /*name*/, SEXP /*val*/) {}
// All three pointer arguments are received and immediately discarded.
//
// If SEXP.h was not already included above, the guard below provides a
