#ifndef FAKE_R_NAMESSYMBOL_DEFINED
#define FAKE_R_NAMESSYMBOL_DEFINED

inline SEXP make_names_symbol() {
    static SEXPREC names_sym = { SYMSXP, 0, 0, 0, NULL };
    return &names_sym;
}

static SEXP R_NamesSymbol = make_names_symbol();

#endif // FAKE_R_NAMESSYMBOL_DEFINED

